export async function bootFlat2() { let sb = null; try { const { createClient } = await import('https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/+esm'); sb = createClient(CONFIG.SUPABASE_URL, CONFIG.SUPABASE_ANON_KEY); const { ssoReceive } = await import('./aou-sso.js'); await ssoReceive(sb); } catch (e) { console.warn('flat offline', e); } const st = document.createElement('style'); st.textContent = FLAT_CSS + FLAT2_CSS; document.head.appendChild(st); const q = new URLSearchParams(location.search); const toast = (m) => { const t = document.createElement('div'); t.textContent = m; t.style.cssText = 'position:fixed;left:50%;top:14px;transform:translateX(-50%);background:#14183a;color:#fff;padding:9px 16px;border-radius:999px;font:700 13px Poppins,Arial;z-index:99;box-shadow:0 8px 24px rgba(0,0,0,.3);max-width:92vw'; document.body.appendChild(t); setTimeout(() => t.remove(), 2800); }; try { localStorage.setItem('aou_mode', 'flat'); if (location.pathname === '/flat/' && !location.search) history.replaceState({}, '', '/'); } catch (e) { } return mountFlat2(document.getElementById('flat') || document.getElementById('flat-root') || document.body, { sb, toast, view: q.get('v') || (q.get('u') ? 'u' : q.get('page') ? 'biz' : q.get('g') ? 'groups' : 'feed'), username: q.get('u'), group: q.get('g'), page: q.get('page'), post: q.get('post') }); }
